// The photograph of a vehicle (FLT-01, D-108).
//
// A photo is a file, so the rules under test are the ones that make a file safe to keep: the type is
// decided by the bytes, the name on disk is generated by the server, a refused row leaves no file
// behind, and removing the photograph takes the index off without pretending the file never existed.
import { describe, expect, it } from "vitest";
import { executeCommand, type AnyCommand } from "./commands";
import { execute, type Actor, type Credential } from "./service";
import { emptyDatabase, emptyRentalSettings, migrate, SCHEMA_VERSION, type Database, type Vehicle, type VehiclePhoto } from "./types";
import {
  executeVehiclePhoto,
  vehiclePhotoLine,
  vehiclePhotoOf,
  vehiclePhotoProblems,
  vehiclesWithoutPhoto,
  VEHICLE_PHOTO_LIMITS,
  type VehiclePhotoUpload,
} from "./vehiclePhoto";

const NOW = "2026-06-01T09:00:00.000Z";
const cred: Credential = { passwordHash: "a".repeat(64), passwordSalt: "b".repeat(32) };

const sha = "a".repeat(64);
const stored = "vhcl_" + "c".repeat(36) + ".jpg";

const upload = (over: Partial<VehiclePhotoUpload> = {}): VehiclePhotoUpload => ({
  originalName: "bus-front.jpg",
  mimeType: "image/jpeg",
  byteSize: 120_000,
  sha256: sha,
  storedName: stored,
  ...over,
});

const photo = (over: Partial<VehiclePhoto> = {}): VehiclePhoto => ({
  storedName: stored,
  originalName: "bus-front.jpg",
  mimeType: "image/jpeg",
  byteSize: 120_000,
  sha256: sha,
  uploadedBy: "Admin",
  uploadedAt: NOW,
  ...over,
});

function build(): { db: Database; admin: Actor; ops: Actor; driver: Actor } {
  const setup = execute(emptyDatabase(), null, { type: "setup_administrator", input: { fullName: "Admin", email: "admin@example.test" }, credential: cred }, NOW);
  if (!setup.ok) throw new Error(setup.message);
  let db = setup.db;
  const admin: Actor = { id: db.users[0].id, fullName: "Admin", role: "administrator" };

  for (const [fullName, role] of [["Ops", "operations"], ["Fin", "finance"]] as const) {
    const created = execute(db, admin, { type: "create_user", input: { fullName, email: `${role}@example.test`, role, active: true }, credential: cred }, NOW);
    if (!created.ok) throw new Error(created.message);
    db = created.db;
  }
  const settings = execute(db, admin, {
    type: "update_settings",
    input: { ...db.settings, currencyCode: "GHS", vehicleCategories: [{ id: "", name: "Coaster", licenceClasses: [] }], shifts: [], rental: emptyRentalSettings() },
  }, NOW);
  if (!settings.ok) throw new Error(settings.message);
  db = settings.db;

  const created = execute(db, admin, {
    type: "create_vehicle",
    input: { registration: "GT 100-26", categoryId: db.settings.vehicleCategories[0].id, make: "", model: "", seatCapacity: "30", notes: "" },
  }, NOW);
  if (!created.ok) throw new Error(created.message);
  db = created.db;

  const ops: Actor = { id: db.users[1].id, fullName: "Ops", role: "operations" };
  // A driver needs a linked driver record to be created, so the denial is checked with the role
  // alone: `authorise` reads the role, and a driver's account holds no `vehicles:update`.
  const driver: Actor = { id: "u-driver", fullName: "Kofi", role: "driver" };
  return { db, admin, ops, driver };
}

function attach(db: Database, actor: Actor, over: Partial<VehiclePhotoUpload> = {}) {
  return executeCommand(db, actor, { type: "attach_vehicle_photo", vehicleId: db.vehicles[0].id, upload: upload(over) }, NOW);
}

describe("what makes a photograph usable", () => {
  it("accepts a JPEG, a PNG or a WebP of a sensible size", () => {
    const { db } = build();
    expect(vehiclePhotoProblems(db, db.vehicles[0].id, upload())).toEqual({});
    expect(vehiclePhotoProblems(db, db.vehicles[0].id, upload({ mimeType: "image/png", storedName: "vhcl_" + "d".repeat(36) + ".png" }))).toEqual({});
  });

  it("refuses a PDF: a vehicle photograph is a picture, and documents have their own register", () => {
    const { db } = build();
    expect(vehiclePhotoProblems(db, db.vehicles[0].id, upload({ mimeType: "application/pdf" })).file).toMatch(/JPEG, a PNG or a WebP/i);
  });

  it("refuses a file that is too big, an empty file, and a name the server did not generate", () => {
    const { db } = build();
    const id = db.vehicles[0].id;
    expect(vehiclePhotoProblems(db, id, upload({ byteSize: VEHICLE_PHOTO_LIMITS.maxBytes + 1 })).file).toMatch(/under 2.0 MB/i);
    expect(vehiclePhotoProblems(db, id, upload({ byteSize: 0 })).file).toMatch(/is empty/i);
    expect(vehiclePhotoProblems(db, id, upload({ storedName: "../../.env" })).file).toMatch(/could not be stored/i);
    expect(vehiclePhotoProblems(db, id, upload({ sha256: "not-a-hash" })).file).toMatch(/could not be read/i);
    expect(vehiclePhotoProblems(db, id, upload({ originalName: "x".repeat(VEHICLE_PHOTO_LIMITS.originalName + 1) })).file).toMatch(/Keep the file name/i);
  });

  it("refuses a vehicle that is not on the register", () => {
    const { db } = build();
    expect(vehiclePhotoProblems(db, "nope", upload()).vehicleId).toMatch(/not on the register/i);
  });
});

describe("filing and taking off the photograph", () => {
  it("files it against the vehicle, with who filed it and when", () => {
    const { db, ops } = build();
    const result = attach(db, ops);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const vehicle = result.db.vehicles[0];
    expect(vehicle.photo).toMatchObject({ storedName: stored, mimeType: "image/jpeg", uploadedBy: "Ops", uploadedAt: NOW });
    expect(result.db.audit[0].action).toBe("vehicles:photo");
    expect(result.message).toMatch(/Photograph filed for GT 100-26/);
  });

  it("replaces the one on file rather than keeping two pictures of the same bus", () => {
    const { db, ops } = build();
    const first = attach(db, ops);
    if (!first.ok) throw new Error("first file failed");

    const second = attach(first.db, ops, { storedName: "vhcl_" + "e".repeat(36) + ".jpg", originalName: "bus-side.jpg" });
    expect(second.ok).toBe(true);
    if (!second.ok) return;
    expect(second.db.vehicles[0].photo?.originalName).toBe("bus-side.jpg");
    // The audit log keeps both statements, so "who changed the picture" is answerable.
    expect(second.db.audit[0].summary).toMatch(/replacing the photograph on file/);
  });

  it("is vehicles:update — a driver cannot file one, and neither can finance", () => {
    const { db, driver } = build();
    const finance: Actor = { id: db.users[2].id, fullName: "Fin", role: "finance" };
    for (const actor of [driver, finance]) {
      const denied = attach(db, actor);
      expect(denied.ok).toBe(false);
      if (!denied.ok) expect(denied.message).toMatch(/Not permitted/);
    }
  });

  it("takes it off with a reason, and leaves the audit trail behind", () => {
    const { db, ops } = build();
    const filed = attach(db, ops);
    if (!filed.ok) throw new Error("file failed");

    const removed = executeCommand(filed.db, ops, { type: "remove_vehicle_photo", vehicleId: filed.db.vehicles[0].id, reason: "Sold to Ama Transport" }, NOW);
    expect(removed.ok).toBe(true);
    if (!removed.ok) return;
    expect(removed.db.vehicles[0].photo).toBe(null);
    expect(removed.db.audit[0].action).toBe("vehicles:photo_remove");
    expect(removed.db.audit[0].summary).toMatch(/Sold to Ama Transport/);
    // The file is not deleted: the message says where it stays.
    expect(removed.message).toMatch(/stays in the folder/i);
  });

  it("refuses a removal with no reason, and one from a vehicle with no photograph", () => {
    const { db, ops } = build();
    const noPhoto = executeCommand(db, ops, { type: "remove_vehicle_photo", vehicleId: db.vehicles[0].id, reason: "Because" }, NOW);
    expect(noPhoto.ok).toBe(false);
    if (!noPhoto.ok) expect(noPhoto.message).toMatch(/no photograph on file/i);

    const filed = attach(db, ops);
    if (!filed.ok) throw new Error("file failed");
    const blankReason = executeCommand(filed.db, ops, { type: "remove_vehicle_photo", vehicleId: filed.db.vehicles[0].id, reason: "  " }, NOW);
    expect(blankReason.ok).toBe(false);
    if (!blankReason.ok) expect(blankReason.errors.reason).toMatch(/without a reason/i);
  });

  it("answers the questions the register asks of it", () => {
    const { db, ops } = build();
    expect(vehiclePhotoOf(db, db.vehicles[0].id)).toBe(null);
    expect(vehiclePhotoLine(null)).toBe("");
    expect(vehiclesWithoutPhoto(db)).toBe(1);

    const filed = attach(db, ops);
    if (!filed.ok) throw new Error("file failed");
    expect(vehiclePhotoOf(filed.db, filed.db.vehicles[0].id)?.originalName).toBe("bus-front.jpg");
    expect(vehiclePhotoLine(photo())).toBe("Filed by Admin on 2026-06-01");
    expect(vehiclesWithoutPhoto(filed.db)).toBe(0);
  });

  it("does not count a retired vehicle among the ones missing a photograph", () => {
    const { db, ops } = build();
    const retired = executeCommand(db, ops, { type: "transition_vehicle", id: db.vehicles[0].id, to: "retired", reason: "Scrapped" }, NOW);
    if (!retired.ok) throw new Error("retire failed");
    expect(vehiclesWithoutPhoto(retired.db)).toBe(0);
    // A retired bus keeps a photograph it already had.
    const filed = executeCommand(db, ops, { type: "attach_vehicle_photo", vehicleId: db.vehicles[0].id, upload: upload() }, NOW);
    if (!filed.ok) throw new Error("file failed");
    const after = executeVehiclePhoto(filed.db, ops, { type: "remove_vehicle_photo", vehicleId: db.vehicles[0].id, reason: "x" }, NOW);
    expect(after.ok).toBe(true);
  });
});

describe("a register written before photographs existed", () => {
  it("reads a vehicle with no photograph as having none", () => {
    const { db } = build();
    const old = { ...db.vehicles[0], photo: undefined } as unknown as Vehicle;
    const migrated = migrate({ ...emptyDatabase(), schemaVersion: 27, vehicles: [old] });
    expect(migrated?.schemaVersion).toBe(SCHEMA_VERSION);
    expect(migrated?.vehicles[0].photo).toBe(null);
  });

  it("keeps a photograph that is already recorded", () => {
    const { db } = build();
    const withPhoto = { ...db.vehicles[0], photo: photo() };
    const migrated = migrate({ ...emptyDatabase(), schemaVersion: 27, vehicles: [withPhoto] });
    expect(migrated?.vehicles[0].photo?.storedName).toBe(stored);
  });
});

describe("the command catalogue", () => {
  it("keeps the file-filing command off the browser's list", async () => {
    const { COMMANDS_WITH_THEIR_OWN_ROUTE, KNOWN_COMMAND_TYPES } = await import("./commandTypes");
    expect((COMMANDS_WITH_THEIR_OWN_ROUTE as readonly string[]).includes("attach_vehicle_photo")).toBe(true);
    expect((KNOWN_COMMAND_TYPES as readonly string[]).includes("remove_vehicle_photo")).toBe(true);
    // Removing touches no file, so it travels through the ordinary command route.
    expect((COMMANDS_WITH_THEIR_OWN_ROUTE as readonly string[]).includes("remove_vehicle_photo")).toBe(false);
  });
});

/** Guarantees the union above stays reachable from the one entry point every screen uses. */
const _commands: AnyCommand[] = [];
void _commands;
